/* Account rename and persisted navigation sorting use app UI rather than WebView prompts. */
(()=>{
const dialog=document.createElement('dialog');dialog.id='renameAccountDialog';dialog.innerHTML='<form class="renameForm"><div class="dialogTop"><strong>修改账号名称</strong><button type="button" onclick="closeAccountRename()">关闭</button></div><input id="renameAccountInput" maxlength="40" autocomplete="off" aria-label="账号名称"><p id="renameAccountError" role="status"></p><div class="tools"><button type="button" onclick="closeAccountRename()">取消</button><button id="renameAccountSave" type="submit">保存</button></div></form>';document.body.append(dialog);
let renaming='',saving=false;
window.openAccountRename=id=>{let accounts=[];try{accounts=JSON.parse(Phone.accounts()||'[]')}catch(e){}const account=accounts.find(a=>a.id===id);if(!account){toast('账号不存在，请重新连接');return}renaming=id;saving=false;$('renameAccountInput').value=account.label||account.name||'';$('renameAccountError').textContent='';$('renameAccountSave').disabled=false;dialog.showModal();$('renameAccountInput').focus();$('renameAccountInput').select()};
window.closeAccountRename=()=>{if(!saving)dialog.close()};
dialog.querySelector('form').onsubmit=e=>{e.preventDefault();if(saving)return;const name=$('renameAccountInput').value.trim();if(!name||name.length>40){$('renameAccountError').textContent='请输入1～40个字的账号名称';return}saving=true;$('renameAccountSave').disabled=true;$('renameAccountError').textContent='正在保存…';Phone.renameAccount(renaming,name)};
window.accountRenameDone=(ok,error)=>{saving=false;$('renameAccountSave').disabled=false;if(ok){dialog.close();accountsChanged();toast('账号名称已更新')}else $('renameAccountError').textContent=error||'保存失败，请重试'};
const drawer=$('pageDrawer'),nav=drawer.querySelector('nav');let drag=null,ghost=null,frame=0,until=0;
function persist(){navigation.pageOrder=[...nav.querySelectorAll('[data-page]')].map(b=>b.dataset.page);const value=JSON.stringify(navigation);if(typeof Phone.saveNavigation==='function')Phone.saveNavigation(value);else localStorage.setItem('navigation',value)}
function reorder(button,target,after){const positions=new Map([...nav.children].map(b=>[b,b.getBoundingClientRect().top]));nav.insertBefore(button,after?target.nextSibling:target);for(const b of nav.children){if(b===button)continue;const shift=positions.get(b)-b.getBoundingClientRect().top;if(shift&&!matchMedia('(prefers-reduced-motion: reduce)').matches){b.getAnimations().forEach(a=>a.cancel());b.animate([{transform:'translateY('+shift+'px)'},{transform:'translateY(0)'}],{duration:170,easing:'cubic-bezier(.2,.8,.2,1)'})}}}
function paint(){frame=0;if(!drag?.active||!ghost)return;ghost.style.top=(drag.y-drag.offset)+'px';const box=drawer.getBoundingClientRect();if(drag.y<box.top+55)drawer.scrollTop-=8;else if(drag.y>box.bottom-55)drawer.scrollTop+=8;const target=[...nav.children].find(b=>b!==drag.button&&drag.y>=b.getBoundingClientRect().top&&drag.y<=b.getBoundingClientRect().bottom);if(target){const rect=target.getBoundingClientRect();reorder(drag.button,target,drag.y>rect.top+rect.height/2)}}
nav.addEventListener('pointerdown',e=>{const button=e.target.closest('[data-page]');if(!button||e.button!==0)return;drag={button,pointer:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,active:false};drag.timer=setTimeout(()=>{if(!drag)return;const rect=button.getBoundingClientRect();drag.active=true;drag.offset=drag.y-rect.top;button.classList.add('navDragging');button.setAttribute('aria-grabbed','true');ghost=button.cloneNode(true);ghost.removeAttribute('onclick');ghost.removeAttribute('data-page');ghost.className='navDragGhost';ghost.tabIndex=-1;ghost.setAttribute('aria-hidden','true');ghost.style.cssText='left:'+rect.left+'px;top:'+rect.top+'px;width:'+rect.width+'px;height:'+rect.height+'px';document.body.append(ghost);button.setPointerCapture(e.pointerId);until=performance.now()+1200;if(typeof Phone.navigationDragStarted==='function')Phone.navigationDragStarted();},320)});
nav.addEventListener('pointermove',e=>{if(!drag)return;drag.y=e.clientY;drag.x=e.clientX;if(!drag.active){if(Math.hypot(drag.x-drag.startX,drag.y-drag.startY)>8){clearTimeout(drag.timer);drag=null;until=performance.now()+300}return}e.preventDefault();until=performance.now()+800;if(!frame)frame=requestAnimationFrame(paint)});
function finish(cancel=false){if(!drag)return;clearTimeout(drag.timer);cancelAnimationFrame(frame);frame=0;const state=drag;drag=null;if(!state.active)return;try{state.button.releasePointerCapture(state.pointer)}catch(e){}state.button.removeAttribute('aria-grabbed');until=performance.now()+450;if(!cancel)persist();const floating=ghost;ghost=null;if(floating){const rect=state.button.getBoundingClientRect();floating.animate([{top:floating.style.top,transform:'scale(1.03)'},{top:rect.top+'px',transform:'scale(1)'}],{duration:160,easing:'cubic-bezier(.2,.8,.2,1)'}).finished.catch(()=>{}).then(()=>{floating.remove();state.button.classList.remove('navDragging')})}else state.button.classList.remove('navDragging')}
nav.addEventListener('pointerup',()=>finish());nav.addEventListener('pointercancel',()=>finish());nav.addEventListener('contextmenu',e=>e.preventDefault());nav.addEventListener('click',e=>{if(performance.now()<until){e.preventDefault();e.stopImmediatePropagation()}},true);
nav.addEventListener('keydown',e=>{const button=e.target.closest('[data-page]');if(!button||!e.altKey||!['ArrowUp','ArrowDown'].includes(e.key))return;const other=e.key==='ArrowUp'?button.previousElementSibling:button.nextElementSibling;if(other){e.preventDefault();reorder(button,other,e.key==='ArrowDown');persist();button.focus()}});
const closeDrawer=window.closePageDrawer;window.closePageDrawer=()=>{finish();closeDrawer()};
})();
